  "hint.act3.heroN8": "📍 다음 할 일: 영웅 {heroCount}/8명 — {remaining}명 더 영입! 행성당 최대 2명 + 가챠 전설의 30%.",
  "hint.act3.cheeksFirst": "📍 다음 할 일: 치크스 적대 행성 1개라도 격파! (TOI-700d, 케플러-452b 등 보라색 1링)",
  "hint.act3.cheeksProg": "📍 다음 할 일: 치크스 {cleared}/5개 격파! {remaining}개 더 처리 → 최종전 자격.",
  "hint.act3.fleet6": "📍 다음 할 일: 함대 {fleetSize}/6척! 거래소·제작소에서 중·대형 함선 추가.",
  "hint.act3.credits500k": "📍 다음 할 일: ₡{credits} → ₡500,000 모으기! 거래/세금/퀘스트.",
  "hint.act3.voidCrystal": "📍 다음 할 일: 보이드 크리스탈 확보! 7링 균열지대(P27~P30) 탐험 → 보스전 진입 재료.",
  "hint.act3.ready": "🎯 최종전 준비 완료! 은하 지도에서 🌍 지구 클릭 → 우르사 메이저 격파 → ACT 4 해방기 시작!",
  "hint.act4.planet20": "📍 다음 할 일: 행성 {ownedCount}/30 정복! 명성 {rep} → {needed}만 더 모으면 +1 보유 한도.",
  "hint.act4.ursaShip": "📍 다음 할 일: 우르사 메이저 함선 획득! 지구 클릭으로 보스전 재도전 (이미 클리어해도 보너스).",
  "hint.act4.hero8": "📍 다음 할 일: 영웅 {heroCount}/8 컴플릿! 마지막 영웅 영입으로 턴 쿨다운 -80초.",
  "hint.act4.endgame": "🌟 ACT 4 엔드게임! 자유 항해 — 보이드 7링 균열 완전 정복 · 신화 함선 컴플릿 · 명성 500+ 도전!",
  "hint.default": "📍 은하계 경로에서 미탐험 행성 찾아봐. 모든 행성 30개가 다 발견 대기 중!",
  "notify.warpAllShipsDone": "⚡ 전 함선 워프 엔진 장착 완료! 은하계 모든 행성으로 순간이동 가능!",
