  "partsGuide.header": "📖 파츠 기능 가이드 — 함선 슬롯에 장착 시 효과",
  "partsGuide.laserT": "⚔️ 레이저 (Laser)",
  "partsGuide.laserD": "<span style=\"color:var(--red)\">ATT</span>(공격력) +5~320 부여. <b>매 턴 자동 발사</b>해 적 함선의 실드를 먼저 깎고 그 다음 HP에 직격. 명중률 100% 보장, 사거리 무제한. 일부 신화 레이저(MW01·RB10)는 가하는 피해의 일정 비율을 자기 HP/실드로 흡수.",
  "partsGuide.missileT": "🚀 미사일 (Missile)",
  "partsGuide.missileD": "<span style=\"color:#ff8844\">ATT</span>(공격력) 부여 + <b>실드 관통</b> 피해. 실드를 통과해 HP 직격하므로 실드형 함선(치크스·아우레우스 기함)에 효과적. 매 턴 1발 발사, 명중률 100%. 신화급(MMB01 이휘소 미사일)은 추가 보이드 데미지.",
  "partsGuide.shieldT": "🛡️ 실드 (Shield)",
  "partsGuide.shieldD": "<span style=\"color:var(--blue)\">INT</span>(실드 강도) 부여 + <b>maxSH</b>(실드 최대량) 증가. 매 턴 자동으로 (INT × 1.5%) 만큼 실드 자가 복구. 미사일은 통과하지만 레이저 피해를 1차로 흡수. 신화급(MS01)은 격침 시 1회 부활.",
  "partsGuide.armorT": "🛡 장갑 (Armor)",
  "partsGuide.armorD": "<b>maxHP</b>(체력 최대량) 증가 + <span style=\"color:var(--gold)\">DEF</span>(방어력) 부여. DEF는 받는 피해를 평탄화. 일부 장갑(RB 시리즈)은 <b>repairRate</b> 보유 → 매 턴 HP 일정% 자동 수리. 신화급(MA01·RB10)은 격침 시 부활 또는 흡혈 능력.",
  "partsGuide.engineT": "⚡ 엔진 (Engine)",
  "partsGuide.engineD": "<span style=\"color:var(--cyan)\">TEC</span>(기술력) 부여 — <b>전투 시 공격속도 증가</b>: <span style=\"color:#cce\">매 턴 먼저 발사 + 선제공격 ATT +20% + 회피율 상승</span>",
  "partsGuide.engineMove": "<b style=\"color:#fff\">행성 이동 거리 3단계</b>:<br><span style=\"color:var(--cyan)\">1단계</span> 일반 엔진 (E01~E12) — <b>인접 1홉</b> 이동 (기본)<br><span style=\"color:var(--gold)\">2단계</span> 전설 엔진 (E15·ME01·SE01 — 함대 중 1척만 보유해도) — <b>2홉</b> 이동<br><span style=\"color:var(--purple)\">3단계</span> 블링크 엔진 (전 함선 워프 장착) — <b>무제한 점프</b> (블랙홀·고리 무시 + 함대 항속 +20%)",
  "codex.loc": "은하계상 위치",
