  "notify.autoFlagshipV2": "🚩 기함 중심 자동 배치 완료 — 파츠 {n}개 · 창고 {c}개",
  "partsGuide.scT": "📦 특수창고 (Special Cargo, SC)",
  "partsGuide.scD": "<b>cargoBonus</b>(화물칸 추가) 부여. 정비소 「창고 확장 전용 슬롯」(함선당 최대 8칸)에 장착. SC01(+4) → SC02(+10) → SC03(+20) → SC04(+32 전설·제작) → SC05(+48 신화). 슬롯 1개 = 전용 슬롯 1칸 점유. 화물칸 합산 최대 80칸.",
