  "prologue.l1": "양자 전송 패킷 수신 완료... {nm} 사령관 정신 동기화 99.8%...",
  "prologue.l2": "어라, 깨어났네? 100년을 기다렸는데 막상 깨어나니까 시시하다.",
  "prologue.l3": "내가 누구냐고? 백구. AI 진돗개. 100년째 폐지 주으면서 위장 상단 세워놨다.",
  "prologue.l4": "{co} 총사령관 {nm}! 할 일은 하나야. 우주 무역·부동산·전투로 돈 벌고 지구 봉쇄한 우르사 메이저 박살내.",
  "prologue.l5": "내가 폐지 주워서 이만큼 세워놨으니, {nm}! 함선 {ship}에 올라타서 전설 영웅들 징발해서 지구 구하러 가자고!",
  "prologue.l6": "P01 프록시마 b — {nm} 사령관 각성. {co} 허브 접속 중...",
  "prologue.systemLabel": "⚡ 시스템",
  "quest.npc.admiral": "제독",
  "quest.npc.broker": "브로커",
  "quest.combat.title1": "해적 함대 소탕",
  "quest.combat.title2": "치크스 정찰대 격퇴",
  "quest.combat.title3": "밀수선 차단",
  "quest.combat.title4": "항로 순찰 지원",
  "quest.combat.desc1": "제독 로한: 이 항로에 해적단이 자리 잡았어. 우리 상선이 매일 털리고 있다네. 자네 함대로 쓸어버려 주게. 사례는 두둑이 챙겨두겠네.",
  "quest.combat.desc2": "제독 로한: 치크스 정찰대 몇 척이 우리 영공에 들어왔다. 격퇴하고 잔해 보고만 해주면 보상은 약속하지. 무리하지 말게.",
  "quest.combat.desc3": "제독 로한: 비밀 정보야. 밀수선 한 척이 곧 이 항로를 지난다. 차단해서 화물을 압수해주면 분담금을 후하게 쳐주지.",
  "quest.combat.desc4": "제독 로한: 우리 순찰대가 손이 모자라네. 자네가 같이 한 바퀴 돌아주면 정식 보수는 챙겨주마. 어렵지 않은 일이야.",
  "quest.delivery.title1": "긴급 화물 배달",
  "quest.delivery.title2": "기밀 문서 전달",
  "quest.delivery.title3": "의약품 이송",
  "quest.delivery.title4": "부품 조달",
  "quest.delivery.desc1": "운송업자 마키: 시간이 없어요. 이 화물을 인접 행성에 그대로 갖다 주시면 됩니다. 운임은 두둑이 드릴 테니 빨리 부탁드려요.",
  "quest.delivery.desc2": "브로커 클라우드: 외교 채널이 막혔어. 자네라면 들키지 않게 문서를 전달할 수 있겠지. 누구한테도 말하지 말고, 그쪽 담당자에게 직접 건네주게.",
  "quest.delivery.desc3": "상인 케인: 내 의약품을 인접 행성으로 배달해줄 수 있겠나? 사례는 하겠네. 가는 동안 해적을 조심하게.",
  "quest.delivery.desc4": "공장장 마티아스: 생산 라인이 멈췄소. 부품 좀 인접 행성에서 가져다 주시면 그 자리에서 현금 박치기 하리다.",
  "quest.gather.title1": "희귀 광물 채취",
  "quest.gather.title2": "방사선 데이터 수집",
  "quest.gather.title3": "잔해 탐색",
  "quest.gather.title4": "물자 회수",
  "quest.gather.desc1": "광물상 라파엘: 인근 소행성대에 희귀 광물이 떴다는 정보야. 2턴 정도 캐오면 시세대로 사겠네. 욕심 부리지 말고 안전하게.",
  "quest.gather.desc2": "연구원 헬렌: 항성풍 방사선 데이터가 필요해요. 2턴 정도 측정 장비 돌려주시면 자료비 깔끔하게 드릴게요. 측정 중에 해적 만나면 즉시 후퇴하세요.",
  "quest.gather.desc3": "고철상 로건: 전투 잔해 구역에 갈 사람을 찾고 있소. 2턴 탐색에 챙겨오는 만큼 나누지. 살아서만 돌아오게.",
  "quest.gather.desc4": "민병대장 호크: 치크스 잔해에 우리 물자가 남아 있소. 회수해 오면 사례하지. 2턴 정도 걸릴 거요 — 정찰대 마주칠 수도 있으니 조심하시오.",
  "quest.explore.title1": "항로 탐색 임무",
  "quest.explore.title2": "성계 측량 지원",
  "quest.explore.title3": "미지 구역 탐사",
  "quest.explore.title4": "위성 궤도 조사",
  "quest.explore.desc1": "제독 로한: 신항로 후보를 자네가 직접 둘러봐 주게. 좌측 [잔해 탐색] 버튼을 누르면 자네 함대가 출동하지. 발견하는 만큼 보고해 주게.",
  "quest.explore.desc2": "항법사 클레어: 이 성계의 좌표 보정이 안 돼 있어요. [잔해 탐색] 버튼 두어 번이면 끝나니까 도와주세요. 보너스로 항법 데이터 사본 드릴게요.",
  "quest.explore.desc3": "제독 로한: 기록이 비어 있는 구역이 있다. 자네가 가서 데이터를 채워 와. 위험하면 후퇴해도 좋다 — 자네 생환이 우선이야.",
  "quest.explore.desc4": "관제관 시오: 위성 궤도 일부가 흔들린다고 보고가 들어왔어요. 한 바퀴 돌면서 어디가 문제인지 확인해 주실래요? 정밀 조사료 따로 챙겨드립니다.",
  "quest.buy.title1": "특산물 매수 의뢰",
  "quest.buy.title2": "진귀품 수집",
  "quest.buy.title3": "대량 발주",
  "quest.buy.title4": "거래 보조",
  "quest.buy.desc1": "거상 이장: 특산물 N개 구해 오시면 시세의 2배로 사들이겠소. 어디서 구해오든 상관없소.",
  "quest.buy.desc2": "수집가 야마다: 진귀한 특산물 N개를 모아 주시오. 거래 기록 남기지 않고 2배 가격에 매입하겠소.",
  "quest.buy.desc3": "도매상 에르마: 우리 거래소에 N개 납품해주시면 시세 2배로 결제합니다. 빠르게 부탁해요.",
  "quest.buy.desc4": "브로커 클라우드: 의뢰자가 급해. 특산물 N개를 즉시 회수해서 가져와. 보상은 시세의 2배.",
  "ui.crewAssign": "👥 크루 배치",
