  "ui.stockQty": "재고 {n}",
  "ui.ambushStats": "사령관 전투력 {plv} vs 해적 {ambush}<br>승률 {pct}%",
  "ui.recruitedHeroesN": "영입 영웅 ({n}/8명)",
  "ui.recruitedHeroesNoCap": "영입 영웅 ({n}명)",
  "ui.skinExplain": "\"함선 외관 위에 <b>{shield}</b>을 씌워서 외부에서 볼 때 디자인이 바뀌어 보이게 하는 거야. 실제 함체·능력치는 그대로! 비용은 해당 함선 정가의 <b>10%</b>야.\"",
  "ui.enhanceExplain": "\"함선 능력치를 한 단계씩 강화. 매 강화 +5%, 최대 +10강(50%). 5강까지는 무조건 성공, 8강부터 실패하면 단계 후퇴! 비용은 1.2배씩 누적 상승.\"",
  "ui.endingShipProse": "D-day 100년 + 1일. AI 진돗개 <b style=\"color:#9ee7ff\">백구</b>의 보고로 동면이 풀렸다. 첫 출항한 함선은 {ship} 한 척. 프록시마 b의 광장에서 {co} 깃발을 내걸고, 사령관은 다시 별 사이의 항로를 그렸다.",
  "ui.openingProseFull": "지구는 한 번 별을 향해 손을 뻗다 거둬졌다. 우르사 메이저의 패권이 태양계로 밀려오던 그날, 인류는 마지막 화물선에 자기 자신을 실어 떠났다. 봉쇄선이 닫혔고, 라디오는 침묵했고, {nm}은(는) 프록시마 b의 동면실에서 눈을 감았다. — 100년이 흘렀다.",
  "ui.chixMirrorProse": "7링의 균열을 따라가던 끝에 진실이 드러났다. <b style=\"color:#cc66ff\">{title}</b>. 우리가 100년 전에 풀어둔 자가학습 군집의 변종. 우리가 만든 것이 우리를 가뒀다. 그날 밤 {nm}은(는) 조타를 놓았고, 백구는 옆에 있었다.",
