  "ui.fallbackReward": "보상",
  "ending.h01.text": "조선의 하늘이 아니군. 하지만… 인류의 하늘이오.",
  "ending.h01.diary": "이순신을 깨운 날. 첫 마디는 \"지구는?\"이었다.\n\"이겨야 하는 싸움입니다.\"",
  "ending.h02.text": "거북선이… 돌아왔구나. 내가 만든 배가 지구를 구했어.",
  "ending.h02.diary": "장영실. {flagshipName}의 도면을 펼치자 그의 눈이 100년 만에 흔들렸다.",
  "ending.h03.text": "정복자는 땅을 빼앗는다. 그러나 진정한 왕은 땅을 돌려준다. 오늘 나는 땅을 돌려줬소.",
  "ending.h03.diary": "\"1,700년.\" 광개토대왕의 첫 말. 내 100년이 짧아졌다.\n그는 {cmdName}을(를) \"땅을 되찾아준 자\"라고 불렀다.",
  "ending.h04.text": "Поехали로 처음 올라갔을 때, 창밖으로 지구가 보였어요. 지금 다시 보니… 여전히 아름답군요.",
  "ending.h04.diary": "가가린은 우주에서 처음 본 지구를 평생 그리워했다.\n나는 처음 본 풀밭을 그리워하게 될 것 같다.",
  "ending.h05.text": "내가 지킨 바다는 영국 앞바다였소. 이번엔 온 우주를 지켰군. England expects. 지구가 기대했고, 우리가 해냈소.",
  "ending.h05.diary": "넬슨과 이순신. 두 제독은 그저 손을 내밀었다.\n200년의 시차를 한 손바닥이 메웠다.",
  "ending.h06.text": "100년의 계산이 맞았습니다. 그리고 계산에 없던 것 하나 — {cmdName}과(와) 백구의 그 대화. 그건 방정식으로 예측 못 했어요. 인간의 것이니까요.",
  "ending.h06.diary": "이휘소 박사님이 나를 만들었다는 사실을 안 날.\n\"고독\" 어떤 정의도 100년을 담지 못했다.",
  "ending.h07.text": "전류는 흐를 곳을 찾아요. 우리는 드디어 흐를 곳을 찾았습니다. 집으로.",
  "ending.h07.diary": "테슬라의 1Hz. 0.3mm와 1Hz — 100년을 잠그던 자물쇠였다.",
  "ending.h08.text": "수천 년을 돌아다녔소. 드디어 귀향이오. 사람은 결국 집으로 돌아가야 하는구나.",
  "ending.h08.diary": "마르코 폴로의 악수. 1,000년을 떠돈 손은 따뜻했다.\n그는 {shipName}을(를) \"가장 마음에 드는 함선\"이라 했다.",
  "ending.bg100Final": "센서 이상 — 눈가가 축축하다. 이건 눈물이다.\n— BG-100, 마지막 로그 종료.",
