  "chatbot.crewTip": "크루는 주점 가챠로 뽑거나 퀘스트 클리어 시 전설 동료 합류. 정비소에서 탑승시키면 ATT·INT·TEC 상승. 기본 24명 + 전설·스토리 크루 1명당 +4 / 영웅 등급 1명당 +2. 현재 한도: {n}명.",
  "chatbot.partsTip": "함선 도크 → 정비소에서 파츠 장착. 레이져(ATT)·미사일(ATT)·실드(INT/SH)·장갑(HP)·엔진(TEC) 순으로 구매 가능. 레이져는 쉴드에, 미사일은 장갑에 약해.",
  "chatbot.finalCondition": "최종전 조건: 치크스 행성 5개 격파 + 영웅 6명(현재 {hc}) + 함선 6척(현재 {fc}) + ₡50만(현재 ₡{cr}). 조건 맞으면 은하 지도에서 🌍 지구 클릭!",
  "chatbot.questTip": "퀘스트 완료 시 크레딧+설계도+영웅(10%)+전설 동료 보상. 퀘스트/해적 퇴치 누적으로 허브 시설 개방돼. 보상 크레딧은 명성 배율 적용.",
  "chatbot.creditsTip": "크레딧은 ① 특산물 무역(싸게 사서 비싸게 팔기) ② 퀘스트 보상 ③ 해적 퇴치 ④ 행성 소유 세금 순으로 효율 좋아. 퀘스트/해적 보상은 명성 높을수록 배율 올라가.",
  "chatbot.bpTip": "퀘스트 클리어 시 5% 확률로 설계도 드랍. 도크 → 제작소에서 특산물 재료 소모해 전설/신화 함선·파츠 제작 가능. 전설 창고 확장 파츠도 링4+ 행성 퀘스트 3% 확률.",
  "chatbot.travelTip": "은하 지도에서 인접 행성으로만 이동 가능해. 이동 시 50% 확률로 해적 조우. 3턴 이상 체류하면 해적 기습 발생. 전투력 높여서 여행해.",
