  "story.ring1Open": "{nm}, 이제 1링 적대 행성들(보라색)이 열렸어. TOI-700d, 케플러-452b, 우르사-알파 — 거기서 싸워야 해.",
  "story.intro": "{nm}은(는) 우르사 메이저가 이끄는 치크스 봉쇄 함대에 지구가 갇히던 날, 낡은 머스탱 한 척으로 첫 항해에 나섰다. {co}의 깃발 아래 항로를 개척해 자금을 모으고, 잔해를 뒤져 부품을 건지고, 적을 격파하며 한 척 한 척 함대를 키웠다. 곁에는 언제나 AI 동료 백구가 있었다. 가슴에 새긴 목표는 단 하나 — 인류를 옥죄는 봉쇄를 부수고, 푸른 지구를 되찾는 것.",
  "story.finalStep": "{nm}, 드디어 이 순간이 왔어. 지구 봉쇄를 푸는 마지막 단계야.",
  "story.postUrsa": "{nm}, 우르사 메이저는 무너졌지만 우주는 여전히 위험해. 치크스 잔당과 보이드 균열도 정리해야 해.",
