  "ui.enhanceMul": " × 강화 +{lv} (×{mul})",
  "ui.queueWaiting": " · 큐 {n}건 대기",
  "ui.commanderBio": "지구가 치크스 봉쇄 함대에 갇힌 시대, 변방 정거장에서 맨몸으로 시작해 함대를 일군 인물. 무역과 전투, 행성 경영을 넘나들며 인류의 마지막 반격을 준비하는 {co}의 총사령관이다.",
  "ui.victoryLine1": "{nm}!! 해냈어! 진짜로 해냈어!! 100년이야, 100년!! 폐지 줍던 내가 이 순간을 보다니!!",
  "ui.victoryLine2": "{nm}! 우리 진짜 영웅이야! 100년 만에 자유로워진 지구가 우리 사령관을 부르고 있어!",
  "ui.victoryLine3": "{nm}, 검은 함선이 사라졌어! 그리고... 어? 우리 격침된 함선들이 다시 살아났어!",
  "ui.blackShipApprox": "{nm}! 하늘 봐!! 검은색... 검은색 함선이야! 본 적도 없는 형태인데... 저게 도대체 뭐야?!",
