  "chatbot.unclearAsk": "좋은 질문인데 나도 애매해. '제작', '크루', '함선', '영웅' 같은 단어로 다시 물어봐.",
  "chatbot.tradeTip": "행성마다 팩션 특산물이 달라. 전투력·명성 조건 충족해야 고급 특산물 구매 가능해. 싸게 사서 다른 행성에서 팔면 돼. 화물칸 늘리면 한번에 더 많이 실어.",
  "notify.fleetFormationReset": "편대 편성 초기화. 자동 배치(체력·방어 우선)로 복귀.",
