  "garage.shipEnhance": "⚡ 함선 강화",
  "baekgu.askMore": "응? 뭔가 물어봐야 대답하지.",
  "baekgu.lowCredits": "크레딧 거의 없어. 무역이나 퀘스트로 충전해.",
  "baekgu.pirateStrengthened": "해적들이 강해졌어. 조심해.",
