  "baekgu.pirateMax": "해적 전투력 최대치. 최고 장비 갖춰.",
  "baekgu.stayWarning": "같은 자리에 너무 오래 있으면 해적들이 냄새 맡는다. 다음 턴엔 이동해.",
  "baekgu.barelyEscaped": "간신히 따돌렸어. 항로 주의해.",
  "baekgu.escapedJustNow": "겨우 빠져나왔어. 빨리 이 구역 떠나자.",
