  "baekgu.warpAllInstalled": "전 함대 워프 엔진 장착 완료! 이제 은하계 어디든 순간이동할 수 있어. 은하계 경로 열어봐!",
  "baekgu.crewRecruitDeclined": "영입 거절. 현재 크루 유지.",
  "baekgu.voidCrystalGet": "보이드 크리스탈이야! 우르사 메이저 보스전 진입 재료. 이걸로 한 번 더 도전 가능!",
  "baekgu.legendCompDeclined": "전설 동료 영입 거절. 현재 크루 유지.",
  "baekgu.debrisPirates": "잔해 신호 듣고 해적들이 추가로 몰려왔다! 조심해.",
  "baekgu.searchStart": "탐색 시작. 잔해 구역 접근 중.",
  "baekgu.searchNothing": "이번엔 없네. 다시 탐색해봐.",
  "baekgu.searchNothingAlt": "이번엔 별다른 게 없네. 다시 시도해봐.",
  "baekgu.searchCompleteQuest": "잔해 탐색 완료. 퀘스트 보상 받아.",
  "baekgu.heroLocationHint": "소문 하나 — 전설의 영웅 {hero}이(가) {planet}(링 {ring})에서 목격됐대요. 그 행성 퀘스트를 진행하면 만날 수 있을 거예요!",
  "baekgu.searchPartial": "잔해 일부 발견. 계속 탐색해야 해.",
  "baekgu.deliveryArrived": "목적지 도착. 퀘스트 탭에서 보상 받아.",
  "baekgu.loanGranted": "빌려줄게. 빨리 갚아.",
  "baekgu.craftingInProgress": "제작 중이야... 잠깐만 기다려.",
  "baekgu.buyQuestComplete": "매수 의뢰 보고 완료. 보상 받으러 가자.",
  "baekgu.auctionLost": "입찰 경쟁에서 졌어. 더 높게 써야 했는데.",
  "baekgu.tollPaidSafe": "통행세 내고 무사 통과! 안전이 최우선이지~",
  "baekgu.asteroidBelt": "소행성대 돌파야! 방향키나 마우스로 회피, Shift로 레이저, Ctrl로 미사일! 50초 버텨!",
  "baekgu.blackHoleEntry": "블랙홀로 가는 진입로는 치크스(적대) 행성 근처에서만 열려. 치크스 행성이나 그 인접 행성으로 이동한 뒤 다시 시도해.",
  "baekgu.blackHoleGateLocked": "저긴 은하 중심의 블랙홀... 먼저 지구를 해방(우르사 메이저 격파)해야 실마리가 잡힐 거야.",
  "baekgu.earthApproachA": "지구다... 우르사 메이저가 우리를 기다리고 있어. 모든 화력 준비!",
  "baekgu.earthBlockedShort": "지구는 봉쇄됐어. ACT 3에 도달해야 진입할 수 있어!",
  "baekgu.earthApproachB": "지구다... 우르사 메이저가 기다린다. 모든 화력 준비!",
  "baekgu.resistanceZoneHint": "이 구역은 지구 저항군 지역이야. 상점에서 난중일기 영인본 구입하면 이순신 영입 가능해.",
  "baekgu.nanjungHave": "난중일기 있어. 이 행성에 이순신이 있으면 영입 가능해.",
  "baekgu.retreatedStep": "한발 물러섰어. 충분히 강해진 후 다시 도전해도 돼.",
  "baekgu.tollPaidPrideHit": "통행료 냈어. 자존심은 상하지만 함선은 멀쩡하잖아. 다음엔 박살내자.",
  "baekgu.fledStronger": "도망쳤어. 다음엔 더 강해진 다음에 부딪치자.",
  "baekgu.haikjin": "학익진이다! 함대가 양 날개로 포위! 적을 가운데로 몰아넣어. 화력 3배 폭격!",
  "baekgu.einsteinRelativity": "아인슈타인의 상대성 이론! 시간축이 휘어진다! 적은 한 번 맞는데 우린 네 번 친다.",
  "baekgu.teslaHyperspace": "테슬라의 전자기 초공간! 함선 무기가 번개로 변했어! 폭딜의 시작!",
  "baekgu.genesisImpact": "제네시스 임펙트! 영웅들의 의지가 한 점에 모였어! 적은 시공간에서 사라진다.",
  "baekgu.destinationEarth": "데스티네이션 어스!! 8명 영웅의 의지 + 100년 봉쇄를 깬 인류의 분노! 화력 10배! 적은 사라진다 — 우주의 정의를 보여줘!",
  "baekgu.voidPhaseUnlocked": "보이드 페이즈 강제 해금됨. 제타 레티쿨리(P30)로 이동해서 광장 → 제독 의뢰 확인해봐!",
  "baekgu.voidSpearGranted": "보이드가 마지막 시험을 위해 ✦ 보이드의 창을 남겼어. 정비소에서 함선에 장착해 — 최종 결전에서 1대씩 즉시 파괴 가능해.",
  "baekgu.mirrorFleetAwoken": "보이드가 인류 역사상 가장 위대한 5척을 깨워냈어! 능력치는 동일, HP는 두 배. 우리 전술이 답이다 — 일점사부터!",
  "confirm.deleteSave": "모든 저장 데이터를 삭제합니다. 계속하시겠습니까?",
  "confirm.deleteAllLocal": "모든 로컬 저장 데이터 삭제?",
