  "quest.crew.QL01.nm": "가브리엘 드 클리포드",
  "quest.crew.QL01.desc": "우주 마법사. 실드 재생 +30%.",
  "quest.crew.QL02.nm": "오세아누스 카터",
  "quest.crew.QL02.desc": "전설의 우주 파일럿. 회피율+25%.",
  "quest.crew.QL03.nm": "세이라 아크",
  "quest.crew.QL03.desc": "은하 저격수. 선제 공격 확률+40%.",
  "quest.crew.QL04.nm": "카이사르 볼테",
  "quest.crew.QL04.desc": "전설 엔지니어. 수리비 -40%.",
  "quest.crew.QL05.nm": "오로라 셴",
  "quest.crew.QL05.desc": "전설 지휘관. 크루 전원 능력치+15%.",
  "cargo.CH01.nm": "지구 저항군 군용 컨테이너",
  "cargo.CH01.desc": "지구 저항군이 보급 작전에 사용하던 표준형 군용 컨테이너. 내부에는 인류 최후의 희망이 담겨 있다는 낙서가 남아 있다.",
  "cargo.CH02.nm": "메카니카 모듈형 화물칸 Mk.I",
  "cargo.CH02.desc": "메카니카 공화국의 표준 규격 모듈형 화물칸. 정밀 기계 조립품을 안전하게 운반하기 위해 진동 흡수 설계가 적용되었다.",
  "cargo.CH03.nm": "크리그 전투 보급 박스",
  "cargo.CH03.desc": "크리그 전투원들이 원정 시 사용하는 군사 보급 박스. 폭발물부터 식량까지 무엇이든 욱여넣을 수 있도록 내부를 설계했다.",
  "cargo.CH04.nm": "수퍼비아 중력 압축 창고",
  "cargo.CH04.desc": "수퍼비아 귀족 함대에서 사용하는 고급 중력 압축 화물 시스템. 내부 공간을 중력장으로 재배열해 일반 창고보다 훨씬 효율적이다.",
  "cargo.CH05.nm": "치크스 생체 저장 낭",
  "cargo.CH05.desc": "치크스 생체공학 기술로 배양된 유기 저장 낭. 살아 있는 세포막이 화물을 감싸 보호하며 스스로 형태를 변형해 다양한 화물을 수용한다.",
  "cargo.CH06.nm": "아우레우스 황금 금고 모듈",
  "cargo.CH06.desc": "아우레우스 상인 연합의 황금 금고 모듈. 장거리 무역 상인들이 귀중품과 크레딧을 안전하게 보관하기 위해 사용한다.",
  "cargo.CH07.nm": "보이드 차원 포켓",
  "cargo.CH07.desc": "보이드 종족의 불가사의한 차원 접기 기술로 만들어진 포켓 공간. 물리 법칙을 왜곡해 외부 크기와 무관하게 거대한 화물을 수납한다.",
  "cargo.CH08.nm": "이휘소 양자 압축 창고",
  "cargo.CH08.desc": "이휘소 박사가 설계한 양자 중첩 원리 기반의 압축 창고. 양자 상태로 화물을 저장해 이론적으로 무한 용량이 가능하다. 전설적인 희귀품.",
  "cargo.CH09.nm": "광개토 함대 통합 화물창 ⚡전설",
  "cargo.CH09.desc": "광개토 함대 기함급에 탑재되는 전설급 통합 화물창 시스템. 함대 전체 보급을 단독으로 담당할 수 있는 압도적인 적재 능력을 자랑한다.",
  "cargo.CH10.nm": "허블 공간 왜곡 창고 ❖신화",
  "cargo.CH10.desc": "허블 망원경 잔해에서 발견된 고대 외계 기술. 공간 자체를 왜곡해 사실상 무한에 가까운 적재 공간을 생성한다. 퀘스트 보상으로만 획득 가능.",
  "cargo.SC01.nm": "[일반] 소형 화물 컨테이너",
  "cargo.SC01.desc": "[일반] 표준 규격 소형 화물 컨테이너. 장착 함선 화물 +4칸.",
  "cargo.SC02.nm": "[고급] 모듈형 확장 창고",
  "cargo.SC02.desc": "[고급] 진동 흡수 모듈형 확장 창고. 장착 함선 화물 +10칸.",
  "cargo.SC03.nm": "[희귀] 중력 압축 화물고",
  "cargo.SC03.desc": "[희귀] 중력장 재배열 압축 화물고. 장착 함선 화물 +20칸.",
  "cargo.SC04.nm": "[전설] 초공간 화물 매트릭스 ⚡",
  "cargo.SC04.desc": "[전설] 초공간 연속 접힘 화물 매트릭스. 장착 함선 화물 +32칸. 제작소 제작 가능.",
  "cargo.SC05.nm": "[신화] 시공간 압축 무한 창고 ✦",
  "cargo.SC05.desc": "[신화] 시공간 왜곡 기반 사실상 무한 적재 창고. 장착 함선 화물 +48칸.",
  "craft.W15.nm": "신의 철퇴 ⚡전설",
  "craft.W15.desc": "전설 무기. ATT +250. 트루딜.",
  "craft.S15.nm": "신의 방패 ⚡전설",
  "craft.S15.desc": "전설 실드. INT +220. SH +5000.",
  "craft.A15.nm": "절대 방벽 ⚡전설",
  "craft.A15.desc": "전설 장갑. HP +3000.",
  "craft.E15.nm": "블링크 엔진 ⚡전설",
  "craft.E15.desc": "전설 엔진. TEC +200. 순간이동.",
  "craft.MW01.nm": "허메틱 포 ✦신화",
  "craft.MW01.desc": "신화 무기. ATT +320. 연속 공격+40%.",
  "craft.MS01.nm": "크로노스 방벽 ✦신화",
  "craft.MS01.desc": "신화 실드. INT +280. SH +8000. 피격 반사 20%.",
  "craft.MA01.nm": "아다만 선체 ✦신화",
