  "craft.ME01.nm": "타키온 드라이브 ✦신화",
  "craft.ME01.desc": "신화 엔진. TEC +320. 이동 후 ATT+50(1턴).",
  "craft.MMB01.nm": "이휘소 방정식 미사일 ❖신화",
