  "craft.H11.desc": "방어·지원 특화. HP 38,000 / SH 22,000. 함대 전체 실드+20%.",
  "craft.H12.nm": "우르사 파쇄기 🌟",
  "craft.H12.desc": "보이드 전용 함선. HP 75,000. 보스전 실드 관통 특화.",
  "craft.SC04.nm": "[전설] 초공간 화물 매트릭스 ⚡",
  "craft.SC04.desc": "전설급 초공간 연속 접힘 화물 매트릭스. 장착 함선 화물 +16칸.",
  "craft.SC05.nm": "[신화] 차원 격납 특이점 🔭",
  "craft.SC05.desc": "신화급 차원 격납 특이점. 무한에 가까운 화물 적재 공간을 압축 보관. 장착 함선 화물 +48칸.",
  "craft.LGD01.nm": "거북선 ✦신화",
  "craft.LGD01.desc": "신화급 전투함. HP 200,000 / SH 65,000. 호위함 능력치+30%.",
  "craft.LGD02.nm": "워덴클리프 ✦신화",
  "craft.LGD02.desc": "신화급 전투함. HP 175,000 / SH 80,000. 매 턴 적 모듈 비활성화.",
  "craft.LGD03.nm": "렐러티비티 ✦신화",
  "craft.LGD03.desc": "신화급 전투함. HP 245,000 / SH 90,000. 최우선 턴 오더.",
  "craft.RB09.nm": "흡혈 폭격 코어 ⚡전설",
  "craft.RB09.desc": "전설 흡혈 코어. 매 턴 maxHP 12% 회복 + 레이저 발사 시 HP 15%/실드 12% 흡수.",
  "craft.RB10.nm": "영혼 흡수 매트릭스 ✦신화",
  "craft.RB10.desc": "신화 흡수 매트릭스. 매 턴 maxHP 18% 회복 + 레이저 발사 시 HP 20%/실드 18% 흡수 + 격침 시 부활.",
