  "hero.H01.nm": "이순신",
  "hero.H01.sk": "학익진 반사",
  "hero.H02.nm": "장영실",
  "hero.H02.sk": "자동 수리",
  "hero.H03.nm": "광개토대왕",
  "hero.H03.sk": "고구려 트루딜",
  "hero.H04.nm": "유리 가가린",
  "hero.H04.sk": "스텔스 실드",
  "hero.H05.nm": "호레이쇼 넬슨",
  "hero.H05.sk": "해상 봉쇄",
  "hero.H06.nm": "A. 아인슈타인",
  "hero.H06.sk": "시간 역행",
  "hero.H07.nm": "니콜라 테슬라",
  "hero.H07.sk": "연쇄 번개",
  "hero.H08.nm": "마르코 폴로",
  "hero.H08.sk": "실크로드 독점",
  "hero.H01.origin": "이순신(李舜臣, 1545~1598). 조선 중기의 무신. 본관 덕수, 자 여해, 시호 충무. 1576년 무과 급제, 1593년 삼도수군통제사 취임. 임진왜란 때 한산도·명량·노량 등에서 일본 수군을 연전연승으로 격파한 성웅(聖雄)으로, 명량에서는 13척으로 왜선 133척 중 31척을 격파했다. 1598년 노량 해전에서 퇴각하는 적선을 추격하다 유탄에 맞아 전사. 이름의 순(舜)은 요순시대의 순임금처럼 덕이 높은 인물이, 신(臣)은 훌륭한 군주를 보필하는 충신이 되라는 부모의 염원이 담겨 있다.",
  "hero.H01.found": "P22 지하 방공호에서 발견. 지하 벙커에서 해도(海圖)를 그리고 있었다.",
  "hero.H01.stats": "ATT:88 INT:150 DEF:70 HP:120 / 클래스: Pilot / 스킬: 학익진 반사 — 아군 피격 시 30% 확률 데미지 반사",
  "hero.H01.char": "장점: 전술 지능 최고급, 팀 전체 방어력 강화. 단점: 단독 공격력 낮음. 성격: 과묵하고 책임감 강함. 패배를 인정하지 않음.",
  "hero.H01.op": "역사상 가장 많이 이긴 제독을 영입했다. 근데 이 사람은 내가 명령해도 자기 판단대로 한다. 나는 그냥 크레딧 대주는 사람이다.",
  "hero.H02.origin": "장영실(蔣英實). 영(英)은 영특함, 실(實)은 실질. \"진짜 뛰어난 자\"라는 뜻. 조선 시대 최고의 과학자·발명가.",
  "hero.H02.found": "P06 넥서스 프라임에서 발견. 새로운 계산 장치를 설계 중이었다.",
  "hero.H02.stats": "ATT:70 INT:115 DEF:40 HP:110 / 클래스: Eng / 스킬: 자동 수리 — 정비소 함선 수리비 40% 할인",
  "hero.H02.char": "장점: 함선 수리 및 업그레이드 효율 극상. 단점: 전투력이 낮아 방어선이 뚫리면 위험. 성격: 발명에 몰두하면 주변이 안 보임.",
  "hero.H02.op": "장영실이 있으면 함선이 알아서 고쳐진다. 수리비가 40% 깎인다. 근데 새로운 발명품을 테스트하다가 폭발한 적도 있다.",
  "hero.H03.origin": "광개토대왕(廣開土大王). 광(廣)은 넓히다, 개토(開土)는 땅을 열다. \"영토를 크게 넓힌 왕\"이라는 뜻. 고구려 최대 영토를 이룩한 왕.",
  "hero.H03.found": "P23 화성 저항군 기지에서 발견. 화성 지도에 고구려 영역이라고 표시 중이었다.",
  "hero.H03.stats": "ATT:110 INT:80 DEF:60 HP:140 / 클래스: Pilot / 스킬: 고구려 트루딜 — 행성 경매 30% 할인",
  "hero.H03.char": "장점: 공격력+내구도+경매 할인 삼박자. 단점: 지능이 낮아 정밀 전략에는 부적합. 성격: 무조건 앞으로. 퇴각을 모른다.",
  "hero.H03.op": "광개토대왕이 있으면 행성 경매가 30% 싸진다. 역사대로 영토 확장을 돕는다. 고구려 영역이 우주까지 넓어지고 있다.",
  "hero.H04.origin": "유리 가가린(Yuri Gagarin). 인류 최초의 우주비행사. 1961년 지구 궤도 비행 성공. 가가린은 \"공작 지역의 사람\"이라는 러시아 어원.",
  "hero.H04.found": "P24 달 정거장에서 발견. 달 표면에서 지구를 바라보고 있었다.",
  "hero.H04.stats": "ATT:140 INT:100 DEF:30 HP:90 / 클래스: Pilot / 스킬: 스텔스 실드 — 선제 공격 후 3턴 실드 유지",
  "hero.H04.char": "장점: 공격력 영웅 중 최고 수준. 스텔스 선제 기습 후 방어. 단점: 체력과 방어가 낮아 집중 공격에 취약. 성격: 낙관적이고 호기심이 많음.",
  "hero.H04.op": "인류 최초 우주비행사가 함선 포수가 됐다. 역사적인 인물이 이런 곳에... 근데 그는 여기가 행복하다고 한다.",
  "hero.H05.origin": "호레이쇼 넬슨(Horatio Nelson). 영국 역사상 가장 유명한 해군 제독. 트라팔가르 해전에서 프랑스-스페인 연합 함대를 격파.",
  "hero.H05.found": "P13 Kepler-22b에서 발견. 전투 훈련 중 크리그 전사들과 어울리고 있었다.",
  "hero.H05.stats": "ATT:82 INT:65 DEF:45 HP:85 / 클래스: Pilot / 스킬: 해상 봉쇄 — 적 도주 확률 30% 감소",
  "hero.H05.char": "장점: 적 도주 봉쇄로 전리품 확보율 상승. 단점: 특화 능력이 없어 극한 상황에선 평범. 성격: 용맹하고 자신감 넘침. 죽음을 두려워하지 않음.",
  "hero.H05.op": "역사에서 전사한 제독이 우주에서 살아서 싸우고 있다. 본인은 2번째 기회라고 한다. 감사하게 써야겠다.",
  "hero.H06.origin": "알베르트 아인슈타인(Albert Einstein). 상대성 이론의 창시자. E=mc²으로 우주의 물리 법칙을 바꿨다. 아인슈타인은 독일어로 \"돌 하나\"라는 뜻.",
  "hero.H06.found": "P30 제타 레티쿨리에서 발견. 시간 역행 공식을 칠판에 적고 있었다.",
  "hero.H06.stats": "ATT:110 INT:150 DEF:80 HP:100 / 클래스: Eng / 스킬: 시간 역행 — 전투 시 한 번 피격 무효화",
  "hero.H06.char": "장점: 모든 스탯 상위권. 피격 무효화 스킬은 결정적 순간에 게임을 바꾼다. 단점: 영입 조건이 가장 까다로움. 성격: 독립적이고 철학적. 남의 말을 잘 안 듣는다.",
  "hero.H06.op": "아인슈타인을 영입했다. 이제 물리 법칙이 내 편이다. 근데 전투 중에 공식을 계산하느라 딴 짓을 한다. 그래도 피격을 한 번 무효화해준다.",
  "hero.H07.origin": "니콜라 테슬라(Nikola Tesla). 교류 전류의 발명가. 무선 전력 전송 이론의 선구자. 테슬라는 세르비아어로 \"도끼를 든 자\"라는 어원.",
  "hero.H07.found": "P09 TRAPPIST-1e에서 발견. 전기 실험 중 행성 전체에 정전을 일으키고 있었다.",
  "hero.H07.stats": "ATT:90 INT:95 DEF:35 HP:80 / 클래스: Eng / 스킬: 연쇄 번개 — 광역 전기 데미지",
  "hero.H07.char": "장점: 광역 공격으로 다수 적 동시 타격. 단점: 방어와 체력이 낮아 보호가 필요. 성격: 열정적이고 집착적. 발명에 집착하면 주변이 폭발함.",
  "hero.H07.op": "테슬라가 있으면 전기가 사방에서 튄다. 적도 맞고 아군도 가끔 맞는다. 그래도 광역이라 유용하다.",
  "hero.H08.origin": "마르코 폴로(Marco Polo). 13세기 베네치아 탐험가. 실크로드를 따라 동방을 탐험한 최초의 유럽인. 폴로는 이탈리아어로 \"닭\"이라는 뜻인데 그는 닭처럼 생기지 않았다.",
  "hero.H08.found": "P27 글리제 581g 균열에서 발견. 보이드 공간에서 새 무역 루트를 지도에 표시 중이었다.",
  "hero.H08.stats": "ATT:120 INT:90 DEF:25 HP:80 / 클래스: Merch / 스킬: 실크로드 독점 — 행성 판매 수익 10% 보너스",
  "hero.H08.char": "장점: 판매 수익 보너스로 상업 플레이 최적. 공격력도 준수. 단점: 방어가 가장 낮아 전투에선 보호 필요. 성격: 호기심이 극도로 강함. 가보지 않은 곳이 있으면 참지 못함.",
  "hero.H08.op": "마르코 폴로 덕분에 수익이 10% 오른다. 그는 보이드에서도 무역 루트를 찾고 있었다. 실크로드의 끝은 우주였다.",
  "hero.npc.kimcheolsun.nm": "김철순",
  "hero.npc.parksoi.nm": "박소이",
  "hero.npc.leekangho.nm": "이강호",
  "hero.npc.junghayeon.nm": "정하연",
  "hero.npc.jamesmckenzie.nm": "제임스 매켄지",
