  "hero.npc.pierredubois.nm": "피에르 뒤부아",
  "hero.npc.sophiebeaumont.nm": "소피 보몽",
  "hero.npc.dmitriivanov.nm": "드미트리 이바노브",
  "hero.npc.natashapetrova.nm": "나타샤 페트로바",
  "hero.npc.carlossilva.nm": "카를로스 실바",
  "hero.npc.mariagonzalez.nm": "마리아 곤잘레스",
  "hero.npc.rashidaltariq.nm": "라시드 알타리크",
