  "part.ML01.nm": "타우 미사일",
  "part.ML01.desc": "[F06 지구저항군] 이강호 박사 개발. 게릴라전용 경량 열추적 미사일. 실드 약세 / 장갑 관통 특화.",
  "part.ML02.nm": "크리그 충격탄",
  "part.ML02.desc": "[F04 크리그] 화산 마그마 코어 폭발 에너지 탄두. 기원지대 전쟁영주 카를로스 승인. 장갑 파괴 전문.",
  "part.ML03.nm": "보이드 파동탄",
  "part.ML03.desc": "[F07 보이드] 반물질 탄두로 공간 왜곡. 라시드 알타리크 연구소 개발. 거리 무관 명중률.",
  "part.ML04.nm": "수퍼비아 중력 미사일",
  "part.ML04.desc": "[F01 수퍼비아] 소피아 모렐 설계. 중력 집속 탄두. 명중 시 적 ENG -20% (1턴 지속).",
  "part.ML05.nm": "메카니카 스마트 미사일",
  "part.ML05.desc": "[F03 메카니카] AI 자율유도. 드미트리 개발. 회피 중인 함선도 추적 명중.",
  "part.ML06.nm": "아우레우스 황금 작살 ⚡전설",
  "part.ML06.desc": "[F02 아우레우스] 전설급 유도 작살. 피에르 발주. 태양핵 에너지 탄두로 DEF 무시 관통 효과.",
  "part.ML07.nm": "치크스 결정 파쇄탄 ⚡전설",
  "part.ML07.desc": "[F05 치크스] 결정석 초고속 파편 미사일. 타기가 제작. 폭발 반경 3칸 광역 타격.",
  "part.MMB01.nm": "이휘소 방정식 미사일 ❖신화",
  "part.MMB01.desc": "[신화급] 고 이휘소 박사의 입자물리 방정식 구현. DEF/SHD 관통 + 크리티칼 +30%. 빛의 속도를 넘어 다각도 공격 다중 충격파 생성.",
  "part.SMIS01.nm": "광개토 봉화 미사일 ◈세트",
  "part.SMIS01.desc": "[광개토 세트(2종)] 보유 시 ATT+100, DEF+40. 광개토대왕(영웅H03) 효과. 봉화 통신 레이더 재머 접목 자율유도.",
  "part.SARM01.nm": "광개토 선체 ◈세트",
  "part.SARM01.desc": "[광개토 세트(2종)] 보유 시 ATT+100, DEF+40. 고구려 철갑 공법 응용. 피격 시 자동 회피 +15%.",
  "part.MW01.nm": "허메틱 포 ✦신화",
  "part.MW01.desc": "신화급 무기. 연속 공격 확률+40%. 상점 미판매.",
  "part.MS01.nm": "크로노스 방벽 ✦신화",
  "part.MS01.desc": "신화급 실드. 피격 반사 20% + 매 턴 maxSH 15% 자가 복구. 상점 미판매.",
  "part.MA01.nm": "아다만 선체 ✦신화",
  "part.MA01.desc": "신화급 장갑. 치명타 피해 50% 감소. 상점 미판매.",
  "part.ME01.nm": "타키온 드라이브 ✦신화",
  "part.ME01.desc": "신화급 엔진. 이동 후 ATT+50 (1턴). 상점 미판매.",
  "part.MMV01.nm": "보이드의 창 ✦신화",
  "part.MMV01.desc": "[신화급 최강 미사일] 보이드 차원의 에너지를 응축한 거대 창. 에너지 충전 후 적 함선 1대를 무조건 즉시 파괴 (재발사 쿨다운 30초). DEF·SHD 완전 관통.",
  "part.SW01.nm": "거북선 함포 ◈세트",
  "part.SW01.desc": "이순신 세트(2종). 보유시 전투 ATT+80 추가.",
  "part.SA01.nm": "거북선 갑옷 ◈세트",
  "part.SA01.desc": "이순신 세트(2종). 보유시 전투 ATT+80 추가.",
  "part.SE01.nm": "테슬라 드라이브 ◈세트",
  "part.SE01.desc": "테슬라 세트(2종). 보유시 전투 INT+100 추가.",
  "part.SS01.nm": "테슬라 장벽 ◈세트",
  "part.SS01.desc": "테슬라 세트(2종). 보유시 전투 INT+100 + 매 턴 maxSH 10% 자가 복구.",
  "part.RB01.nm": "정비 드론",
  "part.RB01.desc": "기초 자동 수리 드론. 매 턴 maxHP 2% 회복",
  "part.RB02.nm": "수리 봇",
  "part.RB02.desc": "중급 자동 수리 봇. 매 턴 maxHP 4% 회복",
  "part.RB03.nm": "자동 정비기",
  "part.RB03.desc": "영웅급 자동 정비기. 매 턴 maxHP 6% 회복",
  "part.RB04.nm": "수리 군단 ⚡전설",
  "part.RB04.desc": "전설 자동 수리 군단. 매 턴 maxHP 10% 회복",
  "part.RB05.nm": "자가 복구 매트릭스 ✦신화",
  "part.RB05.desc": "신화 자가 복구 매트릭스. 매 턴 maxHP 15% 회복 + 격침 시 1회 부활(HP 30%). 상점 미판매.",
  "part.RB06.nm": "흡혈 정비 드론",
  "part.RB06.desc": "적의 에너지 잔열을 회수하는 정비 드론. 매 턴 maxHP 3% 회복 + 레이저 발사 시 피해의 5%만큼 HP 흡수",
  "part.RB07.nm": "적응형 회복 봇",
  "part.RB07.desc": "중급 적응형 회복 봇. 매 턴 maxHP 5% 회복 + 레이저 발사 시 피해의 8%만큼 HP / 5%만큼 실드 흡수",
  "part.RB08.nm": "듀얼 코어 정비 시스템",
  "part.RB08.desc": "영웅급 듀얼 코어 정비 시스템. 매 턴 maxHP 8% 회복 + 레이저 발사 시 피해의 10%만큼 HP / 8%만큼 실드 흡수",
  "part.RB09.nm": "흡혈 폭격 코어 ⚡전설",
  "part.RB09.desc": "전설 흡혈 코어. 매 턴 maxHP 12% 회복 + 레이저 발사 시 피해의 15%만큼 HP / 12%만큼 실드 흡수. 상점 미판매 (설계도 제작)",
  "part.RB10.nm": "영혼 흡수 매트릭스 ✦신화",
  "part.RB10.desc": "신화 영혼 흡수 매트릭스. 매 턴 maxHP 18% 회복 + 레이저 발사 시 피해의 20%만큼 HP / 18%만큼 실드 흡수. 격침 시 1회 부활(HP 50%). 상점 미판매 (설계도 제작)",
