  "ship.H01.desc": "중장갑 순양함. 탑승 크루 LOY+10",
  "ship.H02.nm": "레기온",
  "ship.H02.desc": "편대 지원형. 매 턴 종료 시 함대 전 함선 HP +1.5%/레기온 (최대 +15%, 10척 보유 시 캡)",
