  "npc.wolfVigilante": "볼프 자경단",
  "npc.aureusCustoms": "아우레우스 세관",
  "npc.oscar": "오스카르",
  "npc.peddler": "정거장 행상",
  "npc.corvinus": "코르비누스",
  "npc.navAi": "항법 AI",
  "npc.volcan": "반란군 리더 볼칸",
  "npc.chiksVanguard": "치크스 전위대",
  "npcLore.aori.role": "트레이딩 포스트 상인",
  "npcLore.aori.desc": "100년 만에 깨어난 사령관의 첫 거래를 트게 해준 P03 볼프 교역소의 늙은 상인. 고철이든 무엇이든 사고판다.",
  "npcLore.wolf_elder.role": "볼프 교역소 원로",
  "npcLore.wolf_elder.desc": "100년 전 한 조선인이 두고 간 데이터 칩 — 거북선 설계도 단편을 사령관에게 건넨 노인.",
  "npcLore.nav_ai.role": "함대 항법 AI",
