  "npcLore.chiks_vanguard.role": "치크스 전위대",
  "npcLore.chiks_vanguard.desc": "지구를 봉쇄한 우르사 메이저(치크스)의 선봉 부대. 적대 구역의 첨병.",
  "npcLore.maximov.role": "은하 레인저",
  "npcLore.maximov.desc": "행성 경매와 치안을 관장하는 레인저. 최종장에서 은하 통치 결의를 선언한다.",
