  "ui.rankStory.1": "첫 전공으로 함장의 자리에 올랐다. 부하들이 비로소 그의 판단을 믿기 시작했다.",
  "ui.rankStory.2": "제독. 하나의 함대를 책임지는 무게를 짊어졌다. 치크스조차 그의 이름을 경계한다.",
