  "reward.creditsLabel": "크레딧",
  "reward.creditsPrefix": "+₡{n}",
  "reward.hiddenQuestDesc": "검은 함선의 약속 — 거대 크레딧 (명성 배율 적용).",
  "reward.hiddenBossTitle": "🌑 히든 보스 격파 — 보이드의 선물",
  "boss.blackfalcon": "🌑 블랙팔콘",
  "boss.blackfalconLore": "침묵의 은하에서 온 자. 이름도, 고향도, 목적도 알 수 없다. 능력치는 렐러티비티의 3배.",
  "boss.blackfalconNumbered": "🌑 블랙팔콘 {idx}/{n}",
  "quest.darkShipHidden": "[히든] 검은 함선의 경고 신호",
  "quest.darkShipDesc": "제타 레티쿨리 상공에 정체불명의 검은색 소형 함선이 출현. 통신 신호가 잡혔지만 정체불명의 노이즈로 가득하다. 응답하면 어떤 사태가 벌어질지... (보상: 거대 크레딧 + 보이드 신호 + 함대 검증)",
  "voidQ.h01.line": "전열을 가다듬으십시오, 사령관. 적의 정체는 모르나, 함대의 진형부터 정비합시다.",
  "voidQ.h03.line": "정복의 기개로 맞서겠소. 보이드든 어둠이든, 두려움은 우리의 적이 아니오.",
  "voidQ.h06.line": "흥미롭군요... 이 신호의 주파수는 일반 공간을 넘어선다. 정말로 보이드의 존재일 가능성이 있어요.",
  "voidQ.h07.line": "전자기 간섭이 폭주합니다! 통신 회로가 망가질 수도 있으니 조심하십시오.",
  "voidQ.h04.line": "우주에 미지의 존재가 있다고 늘 말해왔지. 드디어 만나보는군.",
  "voidQ.h08.line": "1000년 항해에서도 들어본 적 없는 신호다... 이건 새 대륙이야.",
  "voidQ.cmdNoHero": "영웅도 없는데 검은 함선이라니. 백구야, 도망갈까?",
  "voidQ.staticNoise": "지지직...... 치직.. 츠츠츠..... 지직...",
  "voidQ.staticShort": "지지직...... 츠츠..",
  "voidQ.staticEnd": "..... 메시지 전송 끝 .....",
  "voidQ.unknown1": "...... 들리는가? .... 들리는...가....",
  "voidQ.unknown2": "지직— 보이드 행성의 총독권을 가져간 존재들이....... 그러한 가치가... 있는지...",
  "voidQ.unknown3": "츠츠즉— ...... 시험해 보겠다.",
  "voidQ.cmdAccept": "좋다. 보이드든 뭐든 — 시험에 응하지. 우리는 100년 봉쇄를 깬 함대다.",
  "voidQ.bkHorrorJoke": "근데 솔직히 말해서, 저 통신 음성... 어디서 많이 들어본 것 같아. 호러 영화에서.",
  "voidQ.cmdBkScold": "백구야, 분위기 좀 깨지 말아줘. 가뜩이나 무서운데.",
  "voidQ.later": "나중에",
  "falconEnd.l1": "음.. 우주에서 이렇게 강한 함대는 1000년만에 처음 만났군.. 좋다..",
  "falconEnd.l2": "그대들의 목표를 지켜보겠다. 하지만 보이드 문명에 선을 넘지는 말길 바란다..",
  "falconEnd.l3": "선물 하나를 하지.. 은하계 가운데로 가볼 수 있다면 내 마지막 시험을 통과할 것이다.",
  "falconEnd.cmd": "은하계 가운데... 블랙홀 말이로군. \"마지막 시험\"이라... 보이드의 모든 별이 우리 손에 들어와야 한다는 뜻일지도.",
  "falconEnd.btnReward": "🎁 보상 수령 ▶",
