  "lock.npcQuest": "제독",
  "lock.npcQuestBase": "아직 자네를 들일 만큼 안전하지 못하네. 인근 해적부터 정리하고 다시 오게.",
  "lock.npcTrade": "상점 주인",
  "lock.npcTradeBase": "가게 문은 닫혔소. 치안이 어수선해서 좌판도 못 펴고 있다오.",
  "lock.npcShip": "도크 매니저",
  "lock.npcShipBase": "우리 격납고는 아직 안전구역이 아니야. 정리되면 환영하겠소.",
  "lock.npcCraft": "제작 장인",
  "lock.npcCraftBase": "화로에 불도 못 붙였어. 일단 인근부터 안전하게 만들어 주시오.",
  "lock.npcGarage": "정비공",
  "lock.npcGarageBase": "공구함을 풀 분위기가 아니오. 문 밖이 시끄럽거든.",
  "lock.npcPlanets": "행정관",
  "lock.npcPlanetsBase": "행정 자료는 안정된 행성에만 공개됩니다. 좀 더 정리해 오시지요.",
  "lock.npcAuction": "경매사",
  "lock.npcAuctionBase": "입찰자들이 무서워서 못 옵니다. 치안부터 챙겨주시면 단상 열겠습니다.",
  "lock.npcFront": "안내인",
  "lock.npcFrontBase": "프론트는 아직 닫혀 있어요. 인근 위협을 먼저 처리해 주세요.",
  "lock.npcDefault": "담당자",
  "lock.npcDefaultBase": "아직은 받아드릴 수 없습니다. 인근을 안전하게 정리해 주세요.",
  "lock.declineF01": "귀족의 응접실은 함부로 열리지 않소이다.",
  "lock.declineF02": "금괴 한 닢이라도 가져오시지. 빈손은 못 들이오.",
  "lock.declineF03": "로그 인증 실패. 해적 데이터 클리어 후 재인증 바람.",
  "heroGreet.H01": "조선의 바다는 저물었으나, 지켜야 할 바다는 여전히 많구려. 사령관, 그 싸움 내가 맡으리다.",
  "heroGreet.H02": "오, 이 함선의 설계도… 손볼 곳이 한두 군데가 아닙니다. 제게 맡겨 주시겠습니까, 사령관?",
  "heroGreet.H03": "이 광활한 우주가 전부 미개척지란 말인가! 사령관, 정복할 별을 보여다오.",
  "heroGreet.H04": "다시 우주로 나갈 수 있다니… Поехали! 갑시다, 사령관!",
  "heroGreet.H05": "England expects… 아니, 이제는 온 인류가 기대하는군. 이 함대, 내가 맡지.",
  "heroGreet.H06": "흥미롭군요. 시간과 공간을 가르는 항해라… 계산이 맞다면, 우리는 반드시 이깁니다.",
  "heroGreet.H07": "전류는 흐를 곳을 찾기 마련이죠. 나의 번개를 적에게 흘려보내 드리겠습니다.",
  "heroGreet.H08": "가보지 않은 항로가 저토록 많은데 가만히 있으라고요? 사령관, 어서 떠납시다!",
  "map.help": "[🖱️ 좌클릭→이동  우클릭→3D회전  휠→줌  행성클릭→선택]",
  "faction.desc.F01": "🏛️ 수퍼비아 — 귀족·정치 중심 문명",
  "faction.desc.F02": "💰 아우레우스 — 금융·자본 중심 문명",
