  "shop.noStock": "재고 없음",
  "shop.noneShort": "없음",
  "voidHint.P27": "어라? 균열에서 이상한 신호가 잡혀. 신호 발원지는 더 깊은 곳… 제타 레티쿨리(P30)로 가야 할 것 같아. 거기서 광장 → 제독 의뢰를 봐.",
  "voidHint.P28": "정체불명의 잡음이 끼고 있어. 신호가 강해지는 방향은 제타 레티쿨리(P30) 쪽. 거기로 가서 광장 → 제독 의뢰 확인해.",
  "voidHint.P29": "균열 너머에 검은 그림자가 보여... 신호 끝점은 제타 레티쿨리(P30)야. 거기 도착하면 광장 → 제독 의뢰에 [히든] 퀘스트가 뜰 거야.",
  "voidHint.P30": "제타 레티쿨리... 여기야! 검은색 함선이 잡혔어! 통신 신호가 — 우리한테 직접 보내는 것 같아. 광장 → 제독 의뢰에 [히든] 의뢰 떴어. 확인해봐!",
  "voidHint.default": "균열에서 미지의 신호가 잡혀. 뭔가 있어.",
