  "toll.boss.hook": "해적 두목 「철갈고리」 보그",
  "toll.boss.hookLine": "어이 거기 함대. 이 항로는 내 구역이야. 통행료 ₡{X}만 내놓으면 곱게 보내주지.",
  "toll.boss.karim": "밀수왕 카림",
  "toll.boss.karimLine": "오, 함선들 좋은데? 흠집 내기 싫으면 ₡{X}만 내. 사업은 사업이니까.",
  "toll.boss.krash": "치크스 군단장 크라쉬",
  "toll.boss.krashLine": "인간 주제에 감히 여기까지. 목숨값으로 ₡{X}를 바쳐라. 그럼 오늘은 살려두마.",
  "toll.boss.veil": "현상금 사냥꾼 베일",
  "toll.boss.veilLine": "네 목에 걸린 현상금보다 ₡{X}가 싸게 먹히겠지? 자, 선택해.",
  "toll.boss.dorga": "약탈자 도르가",
  "toll.boss.dorgaLine": "함선이 아깝지 않냐? ₡{X} 내면 못 본 척 해주마. 거절하면… 후회할걸.",
