  "ursa.fightEnter": "⚔️ 전투 돌입!",
  "ursa.intro.sys1": "⚠️ 워프 신호 감지... 우르사 메이저 함대 출현. 호위 친위대 15척 확인.",
  "ursa.intro.ursa1": "... 인류의 작은 함대가 마침내 여기까지 왔는가.",
  "ursa.intro.ursa2": "100년 전, 우리는 너희 별을 봉인했다. 너희의 침묵은 영원할 줄 알았지.",
  "hof.unnamed": "무명",
  "hof.globalLoading": "🌐 글로벌 명예의 전당 불러오는 중... (최대 15초)",
  "feedback.copyBtn": "📋 복사하기",
  "feedback.sendBtn": "📧 메일 보내기",
  "cheat.confirmBtn": "🔓 확인",
  "backup.slotPrompt": "어느 슬롯에 복원하시겠습니까? (1~8, 기본 1)",
  "backup.commander": "commander",
  "ursa.intro.cmd1": "그 봉쇄, 오늘로 끝이다. 100년의 빚, 지금 갚는다.",
  "ursa.intro.ursa3": "대담하군. 그러나 너희가 본 것은 우리의 그림자뿐. 진짜 모습을 보여주마.",
  "ursa.intro.ursa4": "친위대 알파, 베타, 감마, 델타, 엡실론 — 전열을 정비하라!",
  "ursa.intro.bk": "전투력 1천만! 호위함대까지! 진짜 큰 거 왔어 — 모든 화력을 쏟아부어!",
  "ursa.intro.cmd2": "전 함대, 전열 정비. 첫 일격으로 결판낸다. 발사!",
  "ursa.startFinalBattle": "⚔️ 최종 전투 시작",
  "ursa.later": "잠시 후",
  "ursa.bossName": "우르사 메이저",
  "ursa.phase2Line": "인상적이다.. 하지만 아직 끝나진 않았다. 자.. 한번 막아보아라!",
  "falcon.afterUrsa": "훌륭하다... 내 함대를 모두 꺾었군. 1000년 만에 처음이다. 그렇다면 — 이제 내가 직접 상대해주지.",
  "ursa.outro.1": "... 불가능... 한낱 인간들의 함대가... 100년의 봉인을... 깨버렸단 말인가...",
  "ursa.outro.2": "...크윽... 인정하지... 너희에게는 — 우리가 갖지 못한 그 무엇이 있었다...",
  "ursa.outro.3": "고향으로... 돌아가야 할 이유. 인류의... 그 강한 의지... 그것이 우리를... 무너뜨렸다...",
  "ursa.outro.sys1": "💥 적 기함 우르사 메이저 — 코어 붕괴 확인. 친위대 전멸. 워프 신호 소실.",
  "ursa.outro.bk": "지구 봉쇄가 풀린다! 통신 신호가 들어와! 가족들이... 사람들이... 다시 별을 본대!",
  "ursa.outro.sys2": "📡 지구 통신망 복구. 전 인류로부터의 환호가 은하 전체로 송신되고 있습니다.",
  "ursa.outro.cmd1": "...드디어 끝났다. 100년의 침묵, 100년의 굴종 — 오늘 우리 손으로 청산했다.",
  "ursa.outro.cmd2": "고생했다, 전 함대. 영웅들, 크루들 — 너희 모두의 이름은 인류 역사에 영원히 새겨질 것이다.",
  "ursa.outro.cmd3": "우리는 인류의 길을 열었다. 이제부터 별들은 우리의 친구다 — 그리고 지구는, 영원히 자유다.",
  "ursa.outro.sys3": "🌍 지구 봉쇄 완전 해제. 인류 해방 선언. — DESTINATION EARTH 완수.",
