  "credits.act5Header": "— ACT 5 · 종막 —",
  "credits.journeyHeader": "— 그동안의 여정 —",
  "credits.act1Body": "100년의 봉쇄. 우르사 메이저 함대가 지구를 둘러쌌고, 위장 상단 {co}이(가) 폐지를 주워가며 함대를 일군다. 백구가 {cmd}을(를) 깨운다.",
  "credits.act2Body": "일곱 팩션의 우주. 수퍼비아, 아우레우스, 메카니카, 크리그, 치크스, 지구 저항군, 보이드. {cmd}은(는) 무역과 전투로 함대를 키우고, 전설의 영웅 {n}명을 영입한다.",
  "credits.act3Body": "균열의 너머. 보이드 행성에서 미지의 신호가 잡힌다. 보이드 크리스탈을 모으며 최종전을 준비한다.",
  "credits.act4Body": "지구 해방. 우르사 메이저 격파. 100년의 봉쇄가 끝나고, 인류는 다시 우주로 나간다.",
  "credits.act5Body": "보이드의 심연. 1000년의 침묵을 깬 블랙팔콘과의 결투. 모든 시련을 견뎌낸 사령관은 은하 가운데 블랙홀로 들어간다.",
  "credits.voidQuote": "\"누구도 여기서 살아서 나가지 못한다.<br>네가 원하는걸 해라.\"",
  "ending.prologueHead": "— 프롤로그 · 봉쇄의 100년 —",
  "ending.act1Head": "— 제1막 · 각성 —",
  "ending.act2Head": "— 제2막 · 변경의 불길 —",
  "ending.act3Head": "— 제3막 · 잠든 영웅들 —",
  "ending.act4Head": "— 제4막 · 치크스의 진실 —",
  "ending.act5Head": "— 제5막 · 지구 해방 —",
  "ending.act6Head": "— 제6막 · 보이드의 심연 —",
  "ending.act6Body": "우르사가 남긴 한 마디는 좌표였다. 그곳에는 별빛이 닿지 않는 검은 균열이 있었고, 단 한 줄의 메시지가 떠 있었다. — <i style=\"color:#fff\">\"누구도 여기서 살아서 나가지 못한다. 네가 원하는 걸 해라.\"</i> 우리는 갔다. 알면서도 갔다. 그것이 인간의 방식이었다. 그리고 우리는 — 돌아왔다.",
  "ending.epilogueHead": "— 에필로그 · 귀향 —",
  "ending.epilogueBody": "D-day 100년 + 412일. {ship}은(는) 지구의 풀밭 위에 안착했다. 100년 형광등이 흉내 못 한 색이 사령관의 눈에 비쳤고, 백구의 센서엔 처음 보는 액체가 흘렀다. — 인류는 다시 별을 향해 손을 뻗는다. 이번엔 그 손을 거두지 않는다.",
